import { supabase } from '@/lib/supabase';

export async function fetchStoreSettingsRow() {
  const { data, error } = await supabase.from('store_settings')
    .select('is_store_open, store_name, store_address, free_delivery_threshold, min_order_amount, delivery_fee_per_km, store_latitude, store_longitude')
    .eq('id', 'default')
    .single();
  if (error) throw error;
  return data;
}

export async function upsertStoreSettingsRow(input: {
  isStoreOpen: boolean;
  storeName: string;
  storeAddress: string;
  freeDeliveryThreshold: number;
  minOrderAmount: number;
  latitude: number;
  longitude: number;
}) {
  const { error } = await supabase.from('store_settings').upsert({
    id: 'default',
    is_store_open: input.isStoreOpen,
    store_name: input.storeName,
    store_address: input.storeAddress,
    free_delivery_threshold: input.freeDeliveryThreshold,
    min_order_amount: input.minOrderAmount,
    store_latitude: input.latitude,
    store_longitude: input.longitude,
    updated_at: new Date().toISOString(),
  });
  if (error) throw error;
}
